5483	// H1-C：编辑缓冲的一次提交。窗口声明拥有该节点时，**精确范围增量**（kind 51）
5484	// 是权威通道，整值事件（kind 28）被抑制：消费方只经会话的 Sink 写一次正文，
5485	// 不会出现第二个写入者。未声明（或未开启范围增量）时行为完全不变。
5486	// 系统 TextInput 代理只回调显示全文，所以增量由「已接受的编辑缓冲 → 新文本」
5487	// 复算最小公共前后缀得到：结果文本逐字节等价，区间是它的一个合法表达。
5488	//
5489	// 代理对边界（复核反例）：逐码元取公共前后缀会在代理对中间切分——`😀→😁`
5490	// 得到 `[1,2)` 加一个孤立低代理，`utf16ToUtf8` 又会把它编码成非法 UTF-8。
5491	// 因此两端各自退/扩到**合法标量边界**后才生成替换；重放逐字节等于 next。
5492	// 平台送来畸形 UTF-16（不成对代理）时无法表达成合法增量：具名拒绝、
5493	// 恢复编辑缓冲、owner 零变化。返回 true 表示已交付一次 kind-51。
5494	bool editorEnqueueTextCommit(Session &s, const std::u16string &previous, const std::u16string &next)
5495	{
5496	    const bool ownsNode = editorOwnsTextSession(s);
5497	    if (!ownsNode || previous == next) {
5498	        editorEnqueueTextChanged(s);
5499	        return true;
5500	    }
5501	    size_t prefix = 0;
5502	    const size_t shortest = std::min(previous.size(), next.size());
5503	    while (prefix < shortest && previous[prefix] == next[prefix]) prefix += 1;
5504	    // 前缀必须停在两串的标量边界上（两串前缀段相同，故两串判断同值）。
5505	    if (prefix > 0 && !utf16IsScalarBoundary(previous, prefix)) prefix -= 1;
5506	    size_t suffix = 0;
5507	    const size_t remaining = shortest - prefix;
5508	    while (suffix < remaining &&
5509	           previous[previous.size() - 1 - suffix] == next[next.size() - 1 - suffix]) {
5510	        suffix += 1;
5511	    }
5512	    size_t previousEnd = previous.size() - suffix;
5513	    size_t nextEnd = next.size() - suffix;
5514	    // 后缀起点同样必须合法；不合法就缩短后缀（扩大替换区，保持逐字节等价）。
5515	    while (suffix > 0 &&
5516	           (!utf16IsScalarBoundary(previous, previousEnd) || !utf16IsScalarBoundary(next, nextEnd))) {
5517	        suffix -= 1;
5518	        previousEnd = previous.size() - suffix;
5519	        nextEnd = next.size() - suffix;
5520	    }
5521	    if (previousEnd < prefix) previousEnd = prefix;
5522	    if (nextEnd < prefix) nextEnd = prefix;
5523	    const std::u16string removed = previous.substr(prefix, previousEnd - prefix);
5524	    const std::u16string inserted = next.substr(prefix, nextEnd - prefix);
5525	    if (!utf16IsWellFormed(removed) || !utf16IsWellFormed(inserted)) {
5526	        // 畸形输入：不制造非法增量，恢复编辑缓冲，owner 与本帧提交都保持原状。
5527	        RLOGW("ime range delta refused: malformed_surrogate node=%{public}lld",
5528	              static_cast<long long>(s.editingNodeId));
5529	        s.editingText = previous;
5530	        if (s.caretUtf16 > previous.size()) s.caretUtf16 = static_cast<uint32_t>(previous.size());
5531	        s.caretUtf16 = clampToCodePointBoundary(previous, s.caretUtf16);
5532	        s.selStartUtf16 = s.caretUtf16;
5533	        s.selEndUtf16 = s.caretUtf16;
5534	        return false;
5535	    }
5536	    if (previous != next) {
5537	        s.caretBlinkResetPending = true;
5538	        s.caretAffinity = 0;
5539	    }
5540	    QueuedEvent ev;
5541	    ev.kind = kEvTextRangeChanged;  // 51
5542	    ev.nodeId = s.editingNodeId;
5543	    ev.projectionVersion = s.editingProjectionVersion;
5544	    ev.resourceId = s.editingResourceId;
5545	    ev.nodeKind = s.editingNodeKind;
5546	    ev.selectionStart = static_cast<uint32_t>(prefix);
5547	    ev.selectionEnd = static_cast<uint32_t>(previousEnd);
5548	    ev.text = utf16ToUtf8(inserted);
5549	    ev.bindingEpoch = s.ownedTextSessionBindingEpoch;
5550	    s.events.push_back(ev);
5551	    RLOGI("ime range delta node=%{public}lld range=%{public}u:%{public}u bytes=%{public}zu",
5552	          static_cast<long long>(s.editingNodeId), ev.selectionStart, ev.selectionEnd, ev.text.size());
5553	    return true;
5554	}
