8870	// 无 marked 区间的整值变化 = 一次普通编辑（插入/删除/选区替换）。窗口声明
8871	// 拥有该节点时它就是真实提交，不是视觉预览：系统代理的全文回调在这里转成
8872	// **同版本精确范围增量**交付 owner，视图不被本地草稿遮盖，也不是"提交后才
8873	// 落地"。组字中的变化走 preview_range_ctx（有 marked 区间），仍是预览。
8874	// 返回 true 表示已按提交处理。
8875	bool editorCommitPlainChangeLocked(Session &s, const std::u16string &next)
8876	{
8877	    if (!editorOwnsTextSession(s)) {
8878	        return false;
8879	    }
8880	    // A freshly mounted TextInput can echo the already accepted text before
8881	    // installing its selection. Text alone carries no new caret intention:
8882	    // preserve the placed word/range and any in-flight restoration. A live
8883	    // composition still goes through the settlement/cancellation path below.
8884	    if (next == s.editingText && !s.previewActive && !s.markedActive) return true;
8885	    // 真实提交共同经过这里（onChange 整值变化与无 marked 的预览折入都走本入口）：
8886	    // 人的编辑取代未完成的恢复，取消必须放在共同入口而不是某一个 ABI 外壳里。
8887	    cancelProxyRestoreRequest(s, "human_commit_supersedes");
8888	    const std::u16string previous = s.editingText;
8889	    s.editingText = next;
8890	    s.caretUtf16 = static_cast<uint32_t>(s.editingText.size());
8891	    s.selStartUtf16 = s.caretUtf16;
8892	    s.selEndUtf16 = s.caretUtf16;
8893	    s.previewActive = false;
8894	    s.previewText.clear();
8895	    s.markedActive = false;
8896	    // 畸形输入被具名拒绝时编辑缓冲已由 `editorEnqueueTextCommit` 恢复为
8897	    // previous：这里仍返回 true（该变化由提交路径处理完毕），否则调用方会把
8898	    // 同一段畸形文本当成视觉预览再贴回来。
8899	    const bool committed = editorEnqueueTextCommit(s, previous, s.editingText);
8900	    static_cast<void>(committed);
8901	    return true;
