2101	    /// 按位置结算:参数依次为 `ticket`(结算到该票据为止,含)与 `contextEpoch`。
2102	    /// 回执身份必须匹配当前上下文代次,否则这次 ACK 说明
2103	    /// 不了当前镜像的任何事 —— 例如 nodeId 被复用后旧上下文迟到的回执。
2104	    /// 结算批次里只要有一笔被 owner 拒绝,平台代理与 accepted 正文就已经分叉:置
2105	    /// 校准位,阻止后续输入继续以旧坐标写入当前正文。
2106	    /// 返回 true 表示这次结算被采纳。
2107	    public func acknowledge(ticket: Int64, contextEpoch: Int64): Bool {
2108	        if (contextEpoch != this.contextEpoch) {
2109	            this.lastReason = "stale_context_receipt"
2110	            return false
2111	        }
2112	        var settled: Int64 = 0
2113	        var i: Int64 = 0
2114	        while (i < this.pending.size) {
2115	            let item = this.pending[i]
2116	            if (item.ticket > ticket) {
2117	                break
2118	            }
2119	            if (!item.edit.accepted && item.sourceProxyChanged) {
2120	                this.needsCalibration = true
2121	                this.calibrationRecalibrated = false
2122	            }
2123	            settled += 1
2124	            i += 1
2125	        }
2126	        if (settled == 0) {
2127	            this.lastReason = "unknown_pending_ticket"
2128	            return false
2129	        }
2130	        var k: Int64 = 0
2131	        while (k < settled) {
2132	            this.pending.remove(at: 0)
2133	            k += 1
2134	        }
2135	        return true
2136	    }
