2003	        let alignmentBlock = this.selectionAlignmentBlock()
2004	        if (alignmentBlock != "") {
2005	            // Native may still hold coordinates from the previous accepted
2006	            // scene. Do not reinterpret those numbers against the new mirror.
2007	            this.lastReason = alignmentBlock
2008	            return this.edit(this.editSeq, false, -1, this.lastReason)
2009	        }
2010	        if (!this.window.isPrepared()) {
2011	            this.lastReason = this.window.unpreparedReason()
2012	            return this.edit(this.editSeq, false, -1, this.lastReason)
2013	        }
2014	        let lo = if (start16 <= end16) { start16 } else { end16 }
2015	        let hi = if (start16 <= end16) { end16 } else { start16 }
2016	        if (lo < 0) {
2017	            this.lastReason = "negative_range"
2018	            return this.edit(this.editSeq, false, -1, this.lastReason)
2019	        }
2020	        if (hi > this.mirrorUtf16Length) {
2021	            // 超出已准备上下文:具名拒绝并请求按新镜像重新准备,不钳成其他有效位置。
2022	            this.lastReason = CJGUI_RANGE_TEXT_REASON_OUTSIDE_WINDOW
2023	            return this.edit(this.editSeq, false, -1, this.lastReason)
2024	        }
2025	        let baseMirror = this.mirrorRevision
2026	        // 先在镜像里换算:换算失败是**提交前**的具名拒绝(owner 完全没被触碰),与
2027	        // "owner 收到但拒绝"是两类事件 —— 只有后者让平台代理与 accepted 正文分叉。
2028	        let (startByte, endByte) = match (this.window.documentRangeForUtf16(lo, hi - lo)) {
2029	            case Some(r) => r
2030	            case None => (-1, -1)
2031	        }
2032	        if (startByte < 0) {
2033	            this.lastReason = CJGUI_RANGE_TEXT_REASON_NOT_BOUNDARY
2034	            return this.edit(this.editSeq, false, -1, this.lastReason)
2035	        }
2036	        this.ticketSeq += 1
2037	        let ticket = this.ticketSeq
2038	        let outcome = this.window.applyByteEdit(startByte, endByte, text)
2039	        if (outcome.applied) {
2040	            this.editSeq += 1
2041	            // Accepted text may extend beyond the old bounded slice. Resolve the
2042	            // new caret in owner byte coordinates, then project it through the
2043	            // newly materialised slice before exposing another input range.
2044	            let caretByte = startByte + Int64(text.toArray().size)
2045	            this.window.revealByte(caretByte)
2046	            this.mirrorRevision += 1
2047	            this.mirrorUtf16Length = cjguiUtf16Length(this.window.text())
2048	            let localCaretByte = caretByte - this.window.windowStartByte()
2049	            let mappedCaret: ?Int64 = if (this.window.isPrepared() &&
2050	                this.window.contentVersion() == outcome.versionAfter) {
2051	                cjguiUtf8OffsetToUtf16(this.window.text(), localCaretByte)
2052	            } else { None }
2053	            if (let Some(caret16) <- mappedCaret) {
2054	                this.setSelection16(caret16, caret16)
2055	                this.lastReason = ""
2056	            } else {
2057	                // The owner transaction is already accepted. Keep its receipt,
2058	                // but stop further input until the native proxy is recalibrated.
2059	                this.needsCalibration = true
2060	                this.calibrationRecalibrated = false
2061	                this.lastReason = "accepted_caret_unprepared"
2062	            }
2063	            let result = this.edit(this.editSeq, true, outcome.versionAfter, this.lastReason, ticket)
2064	            this.pending.add(CjguiTextSessionPending(ticket, baseMirror, result))
2065	            return result
2066	        }
2067	        this.lastReason = outcome.reason
2068	        let rejected = this.edit(this.editSeq, false, outcome.versionAfter, outcome.reason, ticket)
2069	        this.pending.add(CjguiTextSessionPending(ticket, baseMirror, rejected))
2070	        // 平台代理已经落了字,owner 没有:两侧从这一刻起分叉。
2071	        this.needsCalibration = true
2072	        this.calibrationRecalibrated = false
2073	        return rejected
2074	    }
2075	
2076	    private func edit(seq: Int64, accepted: Bool, versionAfter: Int64, reason: String): CjguiTextSessionEdit {
2077	        return this.edit(seq, accepted, versionAfter, reason, -1)
2078	    }
2079	
2080	    private func edit(seq: Int64, accepted: Bool, versionAfter: Int64, reason: String,
2081	        ticket: Int64): CjguiTextSessionEdit {
2082	        return CjguiTextSessionEdit(seq, ticket, accepted, versionAfter, this.mirrorRevision,
2083	            this.contextEpoch, reason)
2084	    }
2085	
2100	
2101	    /// 按位置结算:参数依次为 `ticket`(结算到该票据为止,含)与 `contextEpoch`。
2102	    /// 回执身份必须匹配当前上下文代次,否则这次 ACK 说明
2103	    /// 不了当前镜像的任何事 —— 例如 nodeId 被复用后旧上下文迟到的回执。
2104	    /// 结算批次里只要有一笔被 owner 拒绝,平台代理与 accepted 正文就已经分叉:置
2105	    /// 校准位,阻止后续输入继续以旧坐标写入当前正文。
2106	    /// 返回 true 表示这次结算被采纳。
2107	    public func acknowledge(ticket: Int64, contextEpoch: Int64): Bool {
2108	        if (contextEpoch != this.contextEpoch) {
2109	            this.lastReason = "stale_context_receipt"
2110	            return false
2111	        }
2112	        var settled: Int64 = 0
2113	        var i: Int64 = 0
2114	        while (i < this.pending.size) {
2115	            let item = this.pending[i]
2116	            if (item.ticket > ticket) {
2117	                break
2118	            }
2119	            if (!item.edit.accepted && item.sourceProxyChanged) {
2120	                this.needsCalibration = true
2121	                this.calibrationRecalibrated = false
2122	            }
2123	            settled += 1
2124	            i += 1
2125	        }
2126	        if (settled == 0) {
2127	            this.lastReason = "unknown_pending_ticket"
2128	            return false
2129	        }
2130	        var k: Int64 = 0
2131	        while (k < settled) {
2132	            this.pending.remove(at: 0)
2133	            k += 1
2134	        }
2135	        return true
2136	    }
2137	
2138	    /// 拒绝后的**第一步**:按 owner 现状重建镜像并推进镜像修订,返回镜像此刻是否可用于
2139	    /// 重新表达范围。此刻校准锁**仍然持有** —— 锁的解除属于平台侧事件(代理已按新镜像
2140	    /// 重新绑定/投影),必须由 `confirmProxyRestored` 带完整身份回执完成:平台在这一步
2141	    /// 之后取 `restorationReceipt()`,恢复完成再交回。
2142	    public func recalibrate(): Bool {
2143	        this.refreshMirror()
2144	        this.calibrationRecalibrated = this.window.isPrepared()
2145	        return this.calibrationRecalibrated
2146	    }
2147	}

