  2	"""H1：系统 IME 全文回调 → 精确 UTF-16 范围增量的差分必须落在合法标量边界。
  3	
  4	反例（指导复核）：`editorEnqueueTextCommit` 逐码元取公共前后缀。`😀→😁` 会得到
  5	`[1,2)` 加一个孤立低代理，重放不是 next，而且 `utf16ToUtf8` 会把孤立代理编码成
  6	非法 UTF-8（ED B8 81 型）。
  7	
  8	抽取 `ohos_renderer.cpp` 的真实差分/编码/边界函数，在宿主 clang++ 下断言：
  9	  * 一次 kind-51 增量的重放 `previous[0,p) + inserted + previous[pe,end)`
 10	    逐字节等于 next（对合法与非合法边界场景都成立）；
 11	  * `inserted` 的 UTF-8 合法且可逆（编码回来的 UTF-16 没有不成对代理）；
 12	  * 两端偏移都是两串的合法标量边界；
 13	  * 畸形 UTF-16（不成对代理）具名拒绝：不产生事件、编辑缓冲保持 previous。
 14	
 15	负控：去掉边界合法化（回到逐码元行为）或让 well-formed 判定恒真，同一二进制
 16	必须失败——证明本测试能判别原缺陷。
 17	"""
 18	import pathlib
 19	import subprocess
 20	import sys
 21	import tempfile
 22	import unittest
 23	
 24	ROOT = pathlib.Path(__file__).resolve().parents[1]
 25	SOURCE = ROOT / "host" / "ohos_renderer.cpp"
 26	INGRESS = ROOT / "host" / "cjgui_ohos_ingress.h"
 27	
 28	MAIN_BODY = r'''
 29	// --- 断言脚手架 ----------------------------------------------------------
 30	static bool replayEquals(const std::u16string &prev, const QueuedEvent &ev,
 31	                         const std::u16string &next) {
 32	  std::u16string replay = prev.substr(0, ev.selectionStart);
 33	  replay += utf8ToUtf16(ev.text);
 34	  replay += prev.substr(ev.selectionEnd);
 35	  return replay == next;
 36	}
 37	static bool insertedIsLegal(const QueuedEvent &ev) {
 38	  const std::string &u8 = ev.text;
 39	  std::u16string back = utf8ToUtf16(u8);
 40	  if (!utf16IsWellFormed(back)) return false;          // 不成对代理（含代理编码）
 41	  return utf16ToUtf8(back) == u8;                       // 规范可逆编码
 42	}
 43	static bool boundariesAreScalar(const std::u16string &prev, const QueuedEvent &ev) {
 44	  return utf16IsScalarBoundary(prev, ev.selectionStart) &&
 45	         utf16IsScalarBoundary(prev, ev.selectionEnd);
 46	}
 47	static void arm(Session &s, const std::u16string &current) {
 48	  s.ownedTextSessionEnabled = true;
 49	  s.rangeEditDeltaRequested = true;
 50	  s.editingNodeId = 107;
 51	  s.ownedTextSessionNodeId = 107;
 52	  s.editingResourceId = 1;
 53	  s.ownedTextSessionResourceId = 1;
 54	  s.editingNodeKind = 10;
 55	  s.ownedTextSessionNodeKind = 10;
 56	  s.editingProjectionVersion = 3;
 57	  s.ownedTextSessionBindingEpoch = 9;
 58	  s.editingText = current;
 59	  s.caretUtf16 = static_cast<uint32_t>(current.size());
 60	  s.selStartUtf16 = s.caretUtf16;
 61	  s.selEndUtf16 = s.caretUtf16;
 62	}
 63	// 一对代理的构造：U+1F600 😀 / U+1F601 😁 / U+1F900（与 😀 共享低代理）。
 64	static const std::u16string kGrin = u"\xD83D\xDE00";
 65	static const std::u16string kBeam = u"\xD83D\xDE01";
 66	static const std::u16string kSharedLow = u"\xD83E\xDE00";
 67	static const std::u16string kLoneLow = u"\xDE00";
 68	static const std::u16string kLoneHigh = u"\xD83D";
 69	
 70	static int checkPair(const std::u16string &prev, const std::u16string &next,
 71	                     int fail) {
 72	  Session s;
 73	  arm(s, prev);
 74	  const bool committed = editorEnqueueTextCommit(s, prev, next);
 75	  if (!committed) return fail;
 76	  if (s.events.size() != 1) return fail + 1;
 77	  const QueuedEvent &ev = s.events.back();
 78	  if (ev.kind != kEvTextRangeChanged) return fail + 2;
 79	  if (!replayEquals(prev, ev, next)) return fail + 3;
 80	  if (!insertedIsLegal(ev)) return fail + 4;
 81	  if (!boundariesAreScalar(prev, ev)) return fail + 5;
 82	  return 0;
 83	}
 84	
 85	int main() {
 86	  // 1. 代理对整对替换：不能切出孤立代理。
 87	  if (int rc = checkPair(kGrin, kBeam, 10)) return rc;
 88	  // 2. 前缀后跟代理对，且替换落在对内。
 89	  if (int rc = checkPair(u"a" + kGrin, u"a" + kBeam, 20)) return rc;
 90	  // 3. 代理对后跟普通字符（后缀命中）。
 91	  if (int rc = checkPair(kGrin + u"x", kBeam + u"x", 30)) return rc;
 92	  // 4. 两侧都有普通字符。
 93	  if (int rc = checkPair(u"x" + kGrin + u"y", u"x" + kBeam + u"y", 40)) return rc;
 94	  // 5. 共享低代理：只有高代理变化。
 95	  if (int rc = checkPair(kGrin, kSharedLow, 50)) return rc;
 96	  // 6. 追加一个代理对（inserted 是整对）。
 97	  if (int rc = checkPair(kGrin, kGrin + kGrin, 60)) return rc;
 98	  // 7. 删除一个代理对（removed 是整对）。
 99	  if (int rc = checkPair(kGrin + kGrin, kGrin, 70)) return rc;
100	  // 8. 空串插入代理对。
101	  if (int rc = checkPair(u"", kGrin, 80)) return rc;
102	  // 9. 纯 ASCII 插入仍是最小区间：[1,1) 插入 "c"（'b' 作为后缀保留）。
103	  {
104	    Session s; arm(s, u"ab");
105	    if (!editorEnqueueTextCommit(s, u"ab", u"acb") || s.events.size() != 1) return 90;
106	    const QueuedEvent &ev = s.events.back();
107	    if (ev.kind != kEvTextRangeChanged || ev.selectionStart != 1 || ev.selectionEnd != 1 ||
108	        ev.text != "c") return 91;
109	  }
110	  // 10. 畸形：新文本里出现孤立低代理 → 具名拒绝、零事件、缓冲保持 previous。
111	  {
112	    Session s; arm(s, u"a" + kGrin);
113	    const std::u16string malformed = u"a" + kLoneLow;
114	    if (editorEnqueueTextCommit(s, u"a" + kGrin, malformed)) return 100;
115	    if (!s.events.empty()) return 101;
116	    if (s.editingText != u"a" + kGrin) return 102;
117	    if (s.caretUtf16 > s.editingText.size()) return 103;
118	    if (!utf16IsScalarBoundary(s.editingText, s.caretUtf16)) return 104;
119	  }
120	  // 11. 畸形：previous 以孤立高代理开头（平台回读被截断）→ 同样拒绝。
121	  {
122	    Session s; arm(s, kLoneHigh);
